    bronze_booksewingneedlecase = { name = "Bronast etui za šivalne igle", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast etui za šivalne igle za knjigoveze." },
    silver_booksewingneedlecase = { name = "Srebrn etui za šivalne igle", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn etui za šivalne igle za knjigoveze." },
