    jewel_set_booksewingneedlecase = { name = "Draguljast etui za šivalne igle", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast etui za šivalne igle za knjigoveze." },
    royal_sovereign_booksewingneedlecase = { name = "Kraljevski suveren etui za šivalne igle", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren etui za šivalne igle z biseri za krono." },
}
local BUILDINGS = {
    booksewingneedlecase_workshop = { name = "Booksewingneedlecase delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
