    sovereign_booksewingneedlecase_palace = { name = "Suverena booksewingneedlecase palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookSewingNeedleCaseMaker.ironStock=12; BookSewingNeedleCaseMaker.bronzeStock=10; BookSewingNeedleCaseMaker.woodStock=14; BookSewingNeedleCaseMaker.leatherStock=12; BookSewingNeedleCaseMaker.silverStock=8; BookSewingNeedleCaseMaker.goldStock=6; BookSewingNeedleCaseMaker.jewelStock=4; BookSewingNeedleCaseMaker.pearlStock=4
BookSewingNeedleCaseMaker.productStock = {}; BookSewingNeedleCaseMaker.buildings = {}; BookSewingNeedleCaseMaker.maker = nil; BookSewingNeedleCaseMaker.activeMaking = {}; BookSewingNeedleCaseMaker.totalProducts = 0; BookSewingNeedleCaseMaker.dayTimer = 0
function BookSewingNeedleCaseMaker.init() BookSewingNeedleCaseMaker.ironStock=12; BookSewingNeedleCaseMaker.bronzeStock=10; BookSewingNeedleCaseMaker.woodStock=14; BookSewingNeedleCaseMaker.leatherStock=12; BookSewingNeedleCaseMaker.silverStock=8; BookSewingNeedleCaseMaker.goldStock=6; BookSewingNeedleCaseMaker.jewelStock=4; BookSewingNeedleCaseMaker.pearlStock=4; BookSewingNeedleCaseMaker.productStock={}; BookSewingNeedleCaseMaker.buildings={}; BookSewingNeedleCaseMaker.maker=nil; BookSewingNeedleCaseMaker.activeMaking={}; BookSewingNeedleCaseMaker.totalProducts=0; BookSewingNeedleCaseMaker.dayTimer=0; print("[BookSewingNeedleCaseMaker] Royal Book Sewing Needle Case Maker System initialized (6 products, 4 buildings)") end
function BookSewingNeedleCaseMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSewingNeedleCaseMaker.maker={name=n or ("Etuijar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Etuijar najet: %s (spretnost: %d)",BookSewingNeedleCaseMaker.maker.name,s),"success") end; return true end
function BookSewingNeedleCaseMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSewingNeedleCaseMaker.build(id) local ok,e=BookSewingNeedleCaseMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSewingNeedleCaseMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSewingNeedleCaseMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSewingNeedleCaseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSewingNeedleCaseMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSewingNeedleCaseMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSewingNeedleCaseMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSewingNeedleCaseMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSewingNeedleCaseMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSewingNeedleCaseMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSewingNeedleCaseMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSewingNeedleCaseMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSewingNeedleCaseMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSewingNeedleCaseMaker.buildings==0 then return false,"Potrebna etuijska delavnica" end; if not BookSewingNeedleCaseMaker.maker then return false,"Potreben etuijar" end; return true end
function BookSewingNeedleCaseMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSewingNeedleCaseMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSewingNeedleCaseMaker.ironStock=BookSewingNeedleCaseMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSewingNeedleCaseMaker.bronzeStock=BookSewingNeedleCaseMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSewingNeedleCaseMaker.woodStock=BookSewingNeedleCaseMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSewingNeedleCaseMaker.leatherStock=BookSewingNeedleCaseMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSewingNeedleCaseMaker.silverStock=BookSewingNeedleCaseMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSewingNeedleCaseMaker.goldStock=BookSewingNeedleCaseMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSewingNeedleCaseMaker.jewelStock=BookSewingNeedleCaseMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSewingNeedleCaseMaker.pearlStock=BookSewingNeedleCaseMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSewingNeedleCaseMaker.maker then t=math.max(1,t-math.floor(BookSewingNeedleCaseMaker.maker.skill/13)) end; table.insert(BookSewingNeedleCaseMaker.activeMaking,{id="booksewingneedlecase_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSewingNeedleCaseMaker.completeMaking(m) local q=1.0+(BookSewingNeedleCaseMaker.getQualityBonus()/100); if BookSewingNeedleCaseMaker.maker then q=q+(BookSewingNeedleCaseMaker.maker.skill/140) end; q=math.min(2.5,q); BookSewingNeedleCaseMaker.productStock[m.productType]=(BookSewingNeedleCaseMaker.productStock[m.productType] or 0)+m.quantity; BookSewingNeedleCaseMaker.totalProducts=BookSewingNeedleCaseMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSewingNeedleCaseMaker.maker then BookSewingNeedleCaseMaker.maker.itemsMade=BookSewingNeedleCaseMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSewingNeedleCaseMaker.maker.skill=math.min(100,BookSewingNeedleCaseMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Etui izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"booksewingneedlecase.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSewingNeedleCaseMaker.update(dt) if not _G.state then return end; BookSewingNeedleCaseMaker.dayTimer=BookSewingNeedleCaseMaker.dayTimer+dt; if BookSewingNeedleCaseMaker.dayTimer>=30 then BookSewingNeedleCaseMaker.dayTimer=0; for i=#BookSewingNeedleCaseMaker.activeMaking,1,-1 do local m=BookSewingNeedleCaseMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSewingNeedleCaseMaker.completeMaking(m); table.remove(BookSewingNeedleCaseMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSewingNeedleCaseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSewingNeedleCaseMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSewingNeedleCaseMaker.getStats() return {ironStock=BookSewingNeedleCaseMaker.ironStock,bronzeStock=BookSewingNeedleCaseMaker.bronzeStock,woodStock=BookSewingNeedleCaseMaker.woodStock,leatherStock=BookSewingNeedleCaseMaker.leatherStock,silverStock=BookSewingNeedleCaseMaker.silverStock,goldStock=BookSewingNeedleCaseMaker.goldStock,jewelStock=BookSewingNeedleCaseMaker.jewelStock,pearlStock=BookSewingNeedleCaseMaker.pearlStock,productStock=BookSewingNeedleCaseMaker.productStock,numBuildings=#BookSewingNeedleCaseMaker.buildings,hasMaker=BookSewingNeedleCaseMaker.maker~=nil,makerName=BookSewingNeedleCaseMaker.maker and BookSewingNeedleCaseMaker.maker.name or "—",makerSkill=BookSewingNeedleCaseMaker.maker and BookSewingNeedleCaseMaker.maker.skill or 0,activeMaking=#BookSewingNeedleCaseMaker.activeMaking,totalProducts=BookSewingNeedleCaseMaker.totalProducts} end
return BookSewingNeedleCaseMaker
